effect.shader:

    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord.xy

   /////////////////////////



   /////////////////////////
    void main ()
    {

        vec2 image_size = getTexSize(inputImg.size);
        float maxF = max(acScreenSize.x, acScreenSize.y);
        vec2 texelSize = 1.0 / vec2(maxF, maxF);

        vec2 TanRyu;
        TanRyu = acScreenNorm.st;

        /////////////////////////

    	vec4 fragColor;

        // vec4 compCol = texture2DCv(comp.texture,acScreenNorm);
        vec4 texColorOri = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 blurCol = texture2DCv(vblur.texture, acScreenNorm.st);

            highp mat3 rgb2yuv = mat3(
                 0.299,     0.587,    0.114,
                -0.14713,  -0.28886,  0.436,
                 0.615,    -0.51499, -0.10001
            );
            highp mat3 yuv2rgb = mat3(
                1.0,  0.0,      1.13983,
                1.0, -0.39465, -0.58060,
                1.0,  2.03211,  0.0
            );
            vec4 expCol = blurCol;
            highp vec3 rgb = expCol.rgb;
            lowp float a = expCol.a;

            rgb = rgb + vec3(0.0)*a;
            rgb = pow(rgb,vec3(1.0/1.0)); //Gamma 
            rgb = rgb * pow(2.0,-exposure);
            vec4 exp = vec4(rgb,a);

            vec4 subb = vec4((texColorOri.rgb-exp.rgb), texColorOri.a);

            vec3 bot = subb.rgb;
            vec3 top = vec3(1,1,1) * exp.a;

            vec3 t = smoothstep(0.5,0.5,bot);
            vec3 result =
                    t * (1. - (1.-2.*(bot-0.5)) * (1.-top)) +
                    (1.-t) * ((2.*bot) * top);

            fragColor = vec4(result,subb.a);

    	gl_FragColor = mix(texColorOri, fragColor, alpha);
    	// }
    }
